13	    public static void main(String[] args) {
14	        System.out.print("是否要开启日志模式(y or n)？");
15	        if("y".equals(scanner.nextLine())) {    //是否打开文件日志
16	            logOn = true;
17	        }
18	        System.out.print("运算模式选择：\n1.读入文件\n2.实时输入\n请选择：");
19	        if(scanner.nextInt() == 1) {            //进行实时计算或者读入文件计算
20	            readFromFile("samples.txt");
21	            calculateExpressions();
22	        } else {
23	            liveCalculate();
24	        }
25	        if(logOn) {
26	            System.out.println("计算完成，日志保存在log.txt中");
27	        }
28	        Log.log("全部计算完成", logOn);
29	        Log.closeStream();
30	    }
