32	     * 实时输入模式
33	     */
34	    private static void liveCalculate() {
35	        while(true) {
36	            scanner = new Scanner(System.in);
37	            System.out.print("请输入表达式(输入q退出)：");
38	            String equation = scanner.nextLine();
39	            if("q".equals(equation)) {
40	                break;
41	            }
42	            equation = equation.replaceAll(" ", "");
43	            infixExpressions.clear();
44	            infixExpressions.add(equation);
45	            calculateExpressions();
46	        }
47	    }
