50	     * 从文件中读取表达式并存入ArrayList
51	     * @param path 文件路径
52	     */
53	    private static void readFromFile(String path) {
54	        try{
55	            BufferedReader bufferedReader = new BufferedReader(new FileReader(new File(path)));
56	            String tempStr = "";
57	            while((tempStr = bufferedReader.readLine()) != null) {
58	                tempStr = tempStr.substring(1, tempStr.length() - 1);
59	                infixExpressions.add(tempStr);
