69	     */
70	    private static void calculateExpressions() {
71	        for(String infixExpression : infixExpressions) {
72	            System.out.println("The infix expression is " + infixExpression);
73	            if(infixExpression.matches(".*[a-zA-Z].*")) {       //如果存在字母则为表达式化简
74	                String postfixExpression = convertToPostfix(addMultiply(infixExpression));
75	                System.out.println("The postfix expression is " + postfixExpression);
76	                System.out.println();
77	            } else {
78	                String postfixExpression = convertToPostfix(infixExpression);
79	                System.out.println("The postfix expression is " + postfixExpression);
80	                double ans = calculatePostfixExpression(postfixExpression);
81	                System.out.printf("The result is %.2f\n\n", ans);
82	            }
83	        }
