91	    private static String addMultiply(String infixExpression) {
92	        int j = 0;
93	        int length = infixExpression.length();
94	        StringBuilder tempBuilder = null;
95	        for(int i = 0; i < length - 1; i ++) {
96	            if((infixExpression.charAt(j) >= 48 && infixExpression.charAt(j) <= 57) && 
