109	    /**
110	     * 将中缀表达式转化为后缀表达式
111	     * 1.初始化一个栈
112	     * 2.逐个读取元素（数字或者操作符）
113	     * 3.如果遇到数字，直接输出
114	     * 4.如果遇到操作符（不考虑括号），如果其优先级大于栈顶元素，就将栈顶弹出，并重复4步骤，否则将该操作符压入栈中（栈为空的时候也直接压栈即可）
115	     * 5.如果遇到左括号(“(“)，直接将其压入栈中，如果遇到右括号(“)”)，循环弹出顶栈元素，直到左括号为止（左括号也需要弹出，右括号不需要压栈），并且输出所有被弹栈顶元素（左括号除外）
116	     * @param infixExpression 中缀表达式
117	     * @return 空格分割的后缀表达式
118	     */
119	    private static String convertToPostfix(String infixExpression) {
120	        Log.log(("开始转化中缀表达式：" + infixExpression + "\n"), logOn);
121	        StringBuilder postfixExpression =  new StringBuilder();
122	        HashMap<String, Integer> priorityOrder = new HashMap<>();
123	        Stack<String> convertStack = new Stack<>();
124	        priorityOrder.put("^", 3);
125	        priorityOrder.put("*", 2);
126	        priorityOrder.put("/", 2);
127	        priorityOrder.put("+", 1);
128	        priorityOrder.put("-", 1);
129	        priorityOrder.put("(", 0);
130	        ArrayList<String> elementList = splitIntoPieces(infixExpression);
131	        for(int i = 0; i < elementList.size(); i ++) {
132	            String element =  elementList.get(i);
133	            if("+".equals(element) || "-".equals(element) || 
134	               "*".equals(element) || "/".equals(element) || 
135	               "(".equals(element) || ")".equals(element) ||
136	               "^".equals(element)) {
137	                if(")".equals(element)) {
138	                    String tempString = null;
139	                    while(!"(".equals(tempString = convertStack.pop())) {
140	                        postfixExpression.append(tempString + " ");
141	                    }
142	                }else if("(".equals(element)){
143	                    convertStack.push(element);
144	                } else{
145	                    if(convertStack.isEmpty() || priorityOrder.get(element) > priorityOrder.get(convertStack.getTop())) {
146	                        convertStack.push(element);
147	                    } else {
148	                        postfixExpression.append(convertStack.pop() + " ");
149	                        i --; 
150	                        continue;
151	                    }
152	                }
153	            }else {
154	                postfixExpression.append(element + " ");
155	            }
156	            Log.log(element, convertStack.toString(), logOn);
157	        }
158	        while(!convertStack.isEmpty()) {
159	            postfixExpression.append(convertStack.pop() + " ");
160	        }
161	        Log.log(("成功转化为后缀表达式：" + postfixExpression.toString().trim() + "\n\n"), logOn);
162	        return postfixExpression.toString().trim();
163	    }
