168	     * @return 元素List
169	     */
170	    private static ArrayList<String> splitIntoPieces(String infixExpression) {
171	        ArrayList<String> elementList = new ArrayList<>();
172	        outer:for(int i = 0; i < infixExpression.length(); i ++) {
173	            for(int j = i; j < infixExpression.length(); j ++) {
174	                if(infixExpression.charAt(j) == '+' || infixExpression.charAt(j) == '-' || 
175	                   infixExpression.charAt(j) == '*' || infixExpression.charAt(j) == '/' || 
176	                   infixExpression.charAt(j) == '(' || infixExpression.charAt(j) == ')' ||
177	                   infixExpression.charAt(j) == '^') {
178	                    if(infixExpression.charAt(i) == '+' || infixExpression.charAt(i) == '-' || 
179	                       infixExpression.charAt(i) == '*' || infixExpression.charAt(i) == '/' || 
180	                       infixExpression.charAt(i) == '(' || infixExpression.charAt(i) == ')' ||
181	                       infixExpression.charAt(i) == '^') {
182	                        elementList.add(infixExpression.substring(i, j + 1));
183	                        i = j;
184	                        break;
185	                    } else {
186	                        elementList.add(infixExpression.substring(i, j));
187	                        i = j - 1;
188	                        break;
189	                    }
190	                }else if(j == infixExpression.length() - 1) {
191	                    elementList.add(infixExpression.substring(i, j + 1));
192	                    break outer;
193	                }
194	            }
195	        }
196	        return elementList;
197	    }
