199	    /**
200	     * 计算后缀表达式的值
201	     * 1.初始化一个栈
202	     * 2.遍历后缀表达式的所有元素
203	     * 3.如果遇到数字，就将其直接压入栈
204	     * 4.如果遇到运算符，就将顶栈的两个元素弹出，将执行该运算之后结果在压入栈内
205	     * 5.遍历结束后，栈内的唯一一个元素就是计算结果。
206	     * @param postfixExpression 后缀表达式
207	     * @return 后缀表达式的结果
208	     */
209	    private static double calculatePostfixExpression(String postfixExpression) {
210	        Log.log(("开始计算后缀表达式：" + postfixExpression + "\n"), logOn);
211	        String[] elementArray = postfixExpression.split(" ");
212	        Stack<Double> calculateStack = new Stack<>();
213	        Double tempAns = 0.0;
214	        for(int i = 0; i < elementArray.length; i ++) {
215	            String element = elementArray[i];
216	            if("+".equals(element) || "-".equals(element) ||
217	               "*".equals(element) || "/".equals(element) ||
218	               "^".equals(element) ) {
219	                ArrayList<Double> tempList = calculateStack.popTwo();
220	                if("+".equals(element)) {
221	                    tempAns = tempList.get(1) + tempList.get(0);
222	                    calculateStack.push(tempAns);
223	                }else if("-".equals(element)) {
224	                    tempAns = tempList.get(1) - tempList.get(0);
225	                    calculateStack.push(tempAns);
226	                }else if("*".equals(element)) {
227	                    tempAns = tempList.get(1) * tempList.get(0);
228	                    calculateStack.push(tempAns);
229	                }else if("/".equals(element)) {
230	                    tempAns = tempList.get(1) / tempList.get(0);
231	                    calculateStack.push(tempAns);
232	                }else if("^".equals(element)) {
233	                    tempAns = Math.pow(tempList.get(1), tempList.get(0));
234	                    calculateStack.push(tempAns);
235	                }
236	            } else {
237	                calculateStack.push(Double.valueOf(element));
238	            }
239	            Log.log(element, calculateStack.toString(), logOn);
240	        }
241	        Log.log("计算完成，结果是：" + calculateStack.getTop() + "\n\n", logOn);
242	        return calculateStack.getTop();
243	    }
244	}
